import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/security/binary-secure.html","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1750586115000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"18f4210595839548d315fcf5c604fa91fabd78f3","time":1750586115000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add binary secure content"}]},"filePathRelative":"security/binary-secure.md"}`),a={name:`binary-secure.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>การวิเคราะห์ว่า binary <code>/rest-api</code> มีอะไร <strong>ฝังอยู่ภายใน (embedded)</strong> หรือเปล่านั้น เราสามารถใช้เทคนิคหลากหลายแบบตามระดับความลึกของการเจาะ เช่น:</p><hr><h2 id="🔍-1-ใช้-strings-ดึงข้อมูลพื้นฐาน" tabindex="-1"><a class="header-anchor" href="#🔍-1-ใช้-strings-ดึงข้อมูลพื้นฐาน"><span>🔍 1. ใช้ <code>strings</code> ดึงข้อมูลพื้นฐาน</span></a></h2><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">strings</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> less</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="สิ่งที่มักจะเห็น" tabindex="-1"><a class="header-anchor" href="#สิ่งที่มักจะเห็น"><span>สิ่งที่มักจะเห็น:</span></a></h3><ul><li>URL, endpoint, SQL statement</li><li>Secret หรือ token ที่ hardcoded</li><li>Path ของไฟล์</li><li>Debug message</li><li>ค่า environment variable</li></ul><p>🟡 <strong>ถ้าเจออะไรแบบนี้:</strong></p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>DB_PASSWORD=supersecret123</span></span></span>
<span class="line"><span class="line"><span>https://api.payment.com/secret_key=abc</span></span></span>
<span class="line"><span class="line"><span>SELECT * FROM users WHERE ...</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>แสดงว่ามี <strong>ข้อมูลสำคัญหลุดเข้าไปใน binary</strong> แล้ว</p><hr><h2 id="🧠-2-วิเคราะห์ด้วย-go-tool-สําหรับ-go-binary" tabindex="-1"><a class="header-anchor" href="#🧠-2-วิเคราะห์ด้วย-go-tool-สําหรับ-go-binary"><span>🧠 2. วิเคราะห์ด้วย <code>go tool</code> (สำหรับ Go Binary)</span></a></h2><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> version</span><span style="color:#9ECBFF;"> rest-api</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> tool</span><span style="color:#9ECBFF;"> nm</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> less</span><span style="color:#6A737D;">     # ดู symbol ทั้งหมด</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> tool</span><span style="color:#9ECBFF;"> objdump</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#6A737D;">       # disassemble ทั้งหมด</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="ดูว่า-binary-ยังมี-debug-info-อยู่หรือไม่" tabindex="-1"><a class="header-anchor" href="#ดูว่า-binary-ยังมี-debug-info-อยู่หรือไม่"><span>ดูว่า binary ยังมี debug info อยู่หรือไม่:</span></a></h3><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">file</span><span style="color:#9ECBFF;"> rest-api</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>ถ้าเห็นว่า:</strong></p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>not stripped</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>หมายถึง binary ยังมี symbol เช่นชื่อ function, variable → ช่วยให้แฮกเกอร์ reverse ได้ง่ายขึ้น</p><p>แต่ในกรณีของคุณ คุณได้ใส่ <code>-ldflags=&quot;-w -s&quot;</code> แล้ว:</p><ul><li><code>-s</code>: ลบ symbol table</li><li><code>-w</code>: ลบ DWARF debugging information <strong>→ ปลอดภัยขึ้น</strong> ✅</li></ul><hr><h2 id="🧩-3-หา-embedded-files-เช่น-embed-fs" tabindex="-1"><a class="header-anchor" href="#🧩-3-หา-embedded-files-เช่น-embed-fs"><span>🧩 3. หา embedded files (เช่น embed.FS)</span></a></h2><p>ถ้าใช้ Go 1.16+ แล้วมีการใช้ <code>//go:embed</code> → ไฟล์อาจฝังไปใน binary</p><h3 id="วิธีดู" tabindex="-1"><a class="header-anchor" href="#วิธีดู"><span>วิธีดู:</span></a></h3><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">strings</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> grep</span><span style="color:#79B8FF;"> -E</span><span style="color:#9ECBFF;"> &#39;\\.html|\\.json|\\.yaml|\\.env|\\.pem|\\.key|\\.txt&#39;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ถ้าเจอชื่อไฟล์พวกนี้แปลว่าอาจ embed ไปใน binary แล้ว เช่น:</p><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>templates/index.html</span></span></span>
<span class="line"><span class="line"><span>config/dev.env</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="🔒-4-ใช้-static-binary-scanner-gosec" tabindex="-1"><a class="header-anchor" href="#🔒-4-ใช้-static-binary-scanner-gosec"><span>🔒 4. ใช้ Static Binary Scanner (Gosec)</span></a></h2><p>ติดตั้ง <a href="https://github.com/securego/gosec" target="_blank" rel="noopener noreferrer">gosec</a>:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> github.com/securego/gosec/v2/cmd/gosec@latest</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>แล้วรัน:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">gosec</span><span style="color:#9ECBFF;"> ./...</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>📌 วิเคราะห์ source code ว่ามี pattern ที่เสี่ยงมั้ย เช่น:</p><ul><li>ใช้ <code>os/exec</code> แบบไม่ sanitize input</li><li>ไม่ validate input</li><li>ใช้ crypto ไม่ปลอดภัย</li></ul><hr><h2 id="🔬-5-ใช้เครื่องมือ-reverse-engineering-แฮกจริง" tabindex="-1"><a class="header-anchor" href="#🔬-5-ใช้เครื่องมือ-reverse-engineering-แฮกจริง"><span>🔬 5. ใช้เครื่องมือ reverse engineering (แฮกจริง)</span></a></h2><h3 id="ถ้าอยากเล่นแบบจริงจัง" tabindex="-1"><a class="header-anchor" href="#ถ้าอยากเล่นแบบจริงจัง"><span>ถ้าอยากเล่นแบบจริงจัง:</span></a></h3><ul><li><a href="https://ghidra-sre.org/" target="_blank" rel="noopener noreferrer">Ghidra</a> – Reverse แบบ GUI</li><li><a href="https://github.com/ReFirmLabs/binwalk" target="_blank" rel="noopener noreferrer">Binwalk</a> – ตรวจหาไฟล์ที่ embed อยู่ใน binary</li><li><code>rizin</code> / <code>radare2</code> – สำหรับแงะ binary go ที่ซับซ้อน</li></ul><hr><h2 id="✅-สิ่งที่ควรตรวจเวลาแงะ-binary-go" tabindex="-1"><a class="header-anchor" href="#✅-สิ่งที่ควรตรวจเวลาแงะ-binary-go"><span>✅ สิ่งที่ควรตรวจเวลาแงะ Binary Go</span></a></h2><table><thead><tr><th>สิ่งที่เจอใน <code>strings</code></th><th>ควรระวังไหม</th></tr></thead><tbody><tr><td><code>.env</code>, <code>DB_PASS</code>, <code>API_KEY</code></td><td>❗ Yes</td></tr><tr><td>URL หรือ IP ภายในระบบ</td><td>🟡 บางครั้ง</td></tr><tr><td>ชื่อ table / column</td><td>⚠️ ถ้าเจาะ SQL</td></tr><tr><td>JWT secret / cookie key</td><td>❗ Yes</td></tr><tr><td>SSH key, .pem, .crt</td><td>❗ Yes</td></tr></tbody></table><hr><h2 id="🔧-สรุปขั้นตอนเบื้องต้น" tabindex="-1"><a class="header-anchor" href="#🔧-สรุปขั้นตอนเบื้องต้น"><span>🔧 สรุปขั้นตอนเบื้องต้น</span></a></h2><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#6A737D;"># ดึง string ทั้งหมด</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">strings</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> tee</span><span style="color:#9ECBFF;"> strings.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># เช็ค symbol table</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> tool</span><span style="color:#9ECBFF;"> nm</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> less</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># disassemble ถ้าจะวิเคราะห์เชิงลึก</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">go</span><span style="color:#9ECBFF;"> tool</span><span style="color:#9ECBFF;"> objdump</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> &gt;</span><span style="color:#9ECBFF;"> disasm.txt</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># ดูไฟล์ embed</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">strings</span><span style="color:#9ECBFF;"> rest-api</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> grep</span><span style="color:#79B8FF;"> -E</span><span style="color:#9ECBFF;"> &#39;\\.env|\\.html|\\.json|\\.pem&#39;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># เช็คว่ามี debug info มั้ย</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">file</span><span style="color:#9ECBFF;"> rest-api</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};